class GostNumberedCanvas(canvas.Canvas):
    """Холст с ГОСТ-нумерацией (титульный лист не нумеруется, со 2-й страницы по центру внизу)."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._saved_page_states = []

    def showPage(self):
        self._saved_page_states.append(dict(self.__dict__))
        self._startPage()

    def save(self):
        num_pages = len(self._saved_page_states)
        for state in self._saved_page_states:
            self.__dict__.update(state)
            if self._pageNumber > 1:
                self.draw_page_number(num_pages)
            canvas.Canvas.showPage(self)
        canvas.Canvas.save(self)

    def draw_page_number(self, page_count):
        self.saveState()
        self.setFont("Times", 11)
        self.setFillColor(colors.black)
        # Номер страницы по центру внизу листа по стандарту ГОСТ 7.32
        self.drawCentredString(A4[0] / 2.0, 12 * mm, str(self._pageNumber))
        self.restoreState()


